  router.delete('/queue',async(req:AdminRequest,res)=>{try{const userIds=Array.isArray(req.body?.userIds)?req.body.userIds:[];const removed=await transaction(async db=>{const r=userIds.length?await db.query('DELETE FROM queue_entries WHERE user_id=ANY($1::uuid[]) RETURNING user_id',[userIds]):await db.query('DELETE FROM queue_entries RETURNING user_id');await audit(db,req,userIds.length?'queue.clear_selected':'queue.clear_all','queue',undefined,{userIds,removed:r.rowCount});return r.rowCount||0});res.json({removed})}catch(e:any){res.status(400).json({error:e.message})}})
  router.post('/queue/force-match',async(req:AdminRequest,res)=>{try{const userIds=Array.isArray(req.body?.userIds)?req.body.userIds:[];if(userIds.length!==2||userIds[0]===userIds[1])return res.status(400).json({error:'Exactly two distinct queued users are required'});const match=await transaction(async db=>{const queued=await db.query(`SELECT q.*,u.steam_verified,u.owns_hl1,u.vac_banned,u.game_banned,u.deleted_at FROM queue_entries q JOIN users u ON u.id=q.user_id WHERE q.user_id=ANY($1::uuid[]) FOR UPDATE`,[userIds]);if(queued.rowCount!==2)throw new Error('Both users must still be queued');for(const row of queued.rows)if(row.deleted_at||!row.steam_verified||!row.owns_hl1||row.vac_banned||row.game_banned)throw new Error('A selected user is not eligible for matchmaking');if(queued.rows[0].game_mode!==queued.rows[1].game_mode)throw new Error('Selected users must have the same game mode');const common=(queued.rows[0].selected_maps||[]).filter((map:string)=>(queued.rows[1].selected_maps||[]).includes(map));if(!common.length)throw new Error('Selected users have no common map');const r=await db.query(`INSERT INTO matches(match_type,game_mode,player1_id,player2_id,maps,selected_map,status,started_at) VALUES($1,$1,$2,$3,$4,$5,'in_progress',NOW()) RETURNING *`,[queued.rows[0].game_mode,userIds[0],userIds[1],common,common[0]]);await db.query('DELETE FROM queue_entries WHERE user_id=ANY($1::uuid[])',[userIds]);await audit(db,req,'queue.force_match','match',r.rows[0].id,{userIds,selectedMap:common[0]});return r.rows[0]});res.status(201).json({match})}catch(e:any){res.status(400).json({error:e.message})}})
