  router.patch('/matches/:id',async(req:AdminRequest,res)=>{const {status,scoreP1,scoreP2,winnerId,serverId,selectedMap}=req.body;if(status!==undefined&&!['pending','completed','cancelled','in_progress'].includes(status))return res.status(400).json({error:'Invalid status'});if(scoreP1!==undefined&&(!Number.isInteger(Number(scoreP1))||Number(scoreP1)<0))return res.status(400).json({error:'Invalid player one score'});if(scoreP2!==undefined&&(!Number.isInteger(Number(scoreP2))||Number(scoreP2)<0))return res.status(400).json({error:'Invalid player two score'});if([status,scoreP1,scoreP2,winnerId,serverId,selectedMap].every(value=>value===undefined))return res.status(400).json({error:'No supported fields'});try{const match=await transaction(async db=>{const current=await db.query('SELECT * FROM matches WHERE id=$1 FOR UPDATE',[req.params.id]);if(!current.rows[0])throw new Error('Match not found');if(winnerId!==undefined&&winnerId!==null&&![current.rows[0].player1_id,current.rows[0].player2_id].includes(winnerId))throw new Error('Winner must be a match participant');if(selectedMap!==undefined&&!(current.rows[0].maps||[]).includes(selectedMap))throw new Error('Selected map is not valid for this match');if(serverId!==undefined){await db.query("UPDATE game_servers SET current_match_id=NULL,status=CASE WHEN status='in_use' THEN 'online' ELSE status END WHERE current_match_id=$1",[req.params.id]);if(serverId){const server=(await db.query('SELECT id FROM game_servers WHERE id=$1 FOR UPDATE',[serverId])).rows[0];if(!server)throw new Error('Server not found');await db.query("UPDATE game_servers SET current_match_id=$1,status='in_use',updated_at=NOW() WHERE id=$2",[req.params.id,serverId])}}const r=await db.query(`UPDATE matches SET status=COALESCE($1,status),score_p1=COALESCE($2,score_p1),score_p2=COALESCE($3,score_p2),winner_id=CASE WHEN $4::text='__unchanged__' THEN winner_id ELSE NULLIF($4,'')::uuid END,server_id=CASE WHEN $5::text='__unchanged__' THEN server_id ELSE NULLIF($5,'')::uuid END,selected_map=COALESCE($6,selected_map),completed_at=CASE WHEN $1 IN ('completed','cancelled') THEN NOW() WHEN $1 IN ('pending','in_progress') THEN NULL ELSE completed_at END WHERE id=$7 RETURNING *`,[status??null,scoreP1??null,scoreP2??null,winnerId===undefined?'__unchanged__':winnerId??'',serverId===undefined?'__unchanged__':serverId??'',selectedMap??null,req.params.id]);if(status==='completed'||status==='cancelled')await db.query("UPDATE game_servers SET current_match_id=NULL,status=CASE WHEN status='in_use' THEN 'online' ELSE status END WHERE current_match_id=$1",[req.params.id]);await audit(db,req,'match.update','match',req.params.id,{before:current.rows[0],after:r.rows[0],reason:req.body.reason||null});return r.rows[0]});res.json({match})}catch(e:any){res.status(400).json({error:e.message})}})
