  router.patch('/tournaments/:id',async(req:AdminRequest,res)=>{const fields:Record<string,string>={name:'name',description:'description',status:'status',maxParticipants:'max_participants',entryFeePoints:'entry_fee_points',prizePoolPoints:'prize_pool_points',prize1st:'prize_1st',prize2nd:'prize_2nd',prize3rd:'prize_3rd',startDate:'start_date',endDate:'end_date',registrationDeadline:'registration_deadline',requiresVip:'requires_vip'};const entries=Object.entries(req.body).filter(([key])=>fields[key]);if(!entries.length)return res.status(400).json({error:'No supported fields'});if(req.body.status!==undefined&&!['registration','in_progress','completed','cancelled'].includes(req.body.status))return res.status(400).json({error:'Invalid tournament status'});for(const key of ['maxParticipants','entryFeePoints','prizePoolPoints','prize1st','prize2nd','prize3rd'])if(req.body[key]!==undefined&&(!Number.isInteger(Number(req.body[key]))||Number(req.body[key])<0))return res.status(400).json({error:`${key} must be a non-negative integer`});try{const tournament=await transaction(async db=>{const before=(await db.query('SELECT * FROM tournaments WHERE id=$1 FOR UPDATE',[req.params.id])).rows[0];if(!before)throw new Error('Tournament not found');const values=entries.map(([,value])=>value===''?null:value),set=entries.map(([key],index)=>`${fields[key]}=$${index+1}`).join(',');const r=await db.query(`UPDATE tournaments SET ${set},updated_at=NOW() WHERE id=$${values.length+1} RETURNING *`,[...values,req.params.id]);await audit(db,req,'tournament.update','tournament',req.params.id,{before,after:r.rows[0]});return r.rows[0]});res.json({tournament})}catch(e:any){res.status(400).json({error:e.message})}})
  router.post('/tournaments/:id/participants',async(req:AdminRequest,res)=>{try{const {userId}=req.body;if(!userId)return res.status(400).json({error:'userId is required'});const participant=await transaction(async db=>{const tournament=(await db.query('SELECT max_participants,current_participants FROM tournaments WHERE id=$1 FOR UPDATE',[req.params.id])).rows[0];if(!tournament)throw new Error('Tournament not found');if(tournament.max_participants&&tournament.current_participants>=tournament.max_participants)throw new Error('Tournament is full');const user=(await db.query('SELECT id FROM users WHERE id=$1 AND deleted_at IS NULL',[userId])).rows[0];if(!user)throw new Error('User not found');const r=await db.query('INSERT INTO tournament_participants(tournament_id,user_id) VALUES($1,$2) RETURNING *',[req.params.id,userId]);await db.query('UPDATE tournaments SET current_participants=current_participants+1,updated_at=NOW() WHERE id=$1',[req.params.id]);await audit(db,req,'tournament.participant.add','tournament',req.params.id,{userId});return r.rows[0]});res.status(201).json({participant})}catch(e:any){res.status(e.code==='23505'?409:400).json({error:e.code==='23505'?'User is already registered':e.message})}})
  router.delete('/tournaments/:id/participants/:userId',async(req:AdminRequest,res)=>{try{await transaction(async db=>{const r=await db.query('DELETE FROM tournament_participants WHERE tournament_id=$1 AND user_id=$2 RETURNING id',[req.params.id,req.params.userId]);if(!r.rows[0])throw new Error('Participant not found');await db.query('UPDATE tournaments SET current_participants=GREATEST(0,current_participants-1),updated_at=NOW() WHERE id=$1',[req.params.id]);await audit(db,req,'tournament.participant.remove','tournament',req.params.id,{userId:req.params.userId})});res.json({ok:true})}catch(e:any){res.status(400).json({error:e.message})}})
  router.delete('/tournaments/:id',async(req:AdminRequest,res)=>{try{await transaction(async db=>{const r=await db.query('DELETE FROM tournaments WHERE id=$1 RETURNING id',[req.params.id]);if(!r.rows[0])throw new Error('Tournament not found');await audit(db,req,'tournament.delete','tournament',req.params.id)});res.json({ok:true})}catch(e:any){res.status(400).json({error:e.message})}})
  router.get('/reports',async(_req,res)=>{try{res.json({items:(await pool.query(`SELECT r.*,reporter.username reporter_username,reported.username reported_username FROM reports r LEFT JOIN users reporter ON reporter.id=r.reporter_id LEFT JOIN users reported ON reported.id=r.reported_id ORDER BY r.created_at DESC LIMIT 200`)).rows})}catch(e:any){sendError(res,e)}})
  router.post('/reports/:id/action',async(req:AdminRequest,res)=>{const {action,notes,durationMinutes}=req.body;if(!notes||!String(notes).trim())return res.status(400).json({error:'Admin notes are required'});try{await transaction(async db=>{const r=await db.query('SELECT * FROM reports WHERE id=$1 FOR UPDATE',[req.params.id]);if(!r.rows[0])throw new Error('Report not found');if(action==='dismiss')await db.query("UPDATE reports SET status='dismissed',admin_notes=$1,reviewed_at=NOW() WHERE id=$2",[notes,req.params.id]);else if(['warning','resolve'].includes(action))await db.query("UPDATE reports SET status='actioned',admin_notes=$1,reviewed_at=NOW() WHERE id=$2",[notes,req.params.id]);else if(['mute','temporary_ban','permanent_ban'].includes(action)){if(action==='mute')await db.query("INSERT INTO user_mutes(user_id,reason,issued_by,expires_at) VALUES($1,$2,$3,NOW()+($4||' minutes')::interval)",[r.rows[0].reported_id,notes,req.adminId,durationMinutes||60]);else await db.query("INSERT INTO bans(user_id,reason,duration_minutes,expires_at,issued_by,ban_type) VALUES($1,$2,$3,CASE WHEN $3::int IS NULL THEN NULL ELSE NOW()+($3||' minutes')::interval END,$4,'platform')",[r.rows[0].reported_id,notes,action==='permanent_ban'?null:(durationMinutes||1440),req.adminId]);await db.query("UPDATE reports SET status='actioned',admin_notes=$1,reviewed_at=NOW() WHERE id=$2",[notes,req.params.id])}else throw new Error('Unsupported action');await audit(db,req,`report.${action}`,'report',req.params.id,{before:r.rows[0],notes,durationMinutes})});res.json({ok:true})}catch(e:any){res.status(400).json({error:e.message})}})
